/**
 * Normalizes file system path to POSIX import path.
 * - Windows '\' → '/'
 * - Removes file extension
 */
export function normalizeImportPath(filePath: string): string {
    return filePath
        .replace(/\\/g, "/")
        .replace(/\.[^/.]+$/, "");
}

/**
 * Converts a file path into its corresponding route URL path.
 *
 * Rules:
 * - "index.tsx"       → "/"
 * - "home/[id].tsx"   → "/home/:id"
 * - "[...slug].tsx"   → "/*"
 * - "404.tsx"         → "*"
 */
export function toRoutePath(filePath: string, baseDir = ""): string {
    let path = normalizeImportPath(filePath);

    // Remove baseDir prefix if present
    if (baseDir) {
        const normalizedBase = baseDir.replace(/\\/g, "/").replace(/\/$/, "");
        if (path.startsWith(normalizedBase)) {
            path = path.slice(normalizedBase.length);
        }
    }

    // Strip route groups e.g. (auth), (public), (dashboard)
    path = path.replace(/(^|\/)\([^)]+\)/g, "");

    // Normalize multiple slashes and ensure leading slash
    path = path.replace(/\/+/g, "/");
    if (!path.startsWith("/")) path = "/" + path;

    // Handle 404 fallback wildcard
    if (path === "/404" || path === "/_404") {
        return "*";
    }

    // Handle catch-all routes: [...slug] -> *
    path = path.replace(/\[\.\.\..+?\]/g, "*");

    // Handle dynamic parameters: [id] -> :id
    path = path.replace(/\[(.+?)\]/g, ":$1");

    // Convert index route: e.g. /home/index -> /home, /index -> /
    if (path.endsWith("/index")) {
        path = path.slice(0, -"/index".length) || "/";
    }

    // Remove trailing slash except for root "/"
    if (path.length > 1 && path.endsWith("/")) {
        path = path.slice(0, -1);
    }

    return path || "/";
}

/**
 * Resolves a file path to its route path (alias for toRoutePath).
 */
export function resolveRoutePath(file: string, baseDir = ""): string {
    return toRoutePath(file, baseDir);
}
