import type { ReactNode } from "react";
import { evaluateGuard } from "./evaluator";
import type { RouteMeta, AuthState, GuardOptions } from "./types";

export interface RouteGuardProps {
    meta?: RouteMeta;
    auth?: AuthState | null;
    options?: GuardOptions;
    children: ReactNode;
    fallback?: ReactNode | ((redirect?: string) => ReactNode);
}

/**
 * RouteGuard component for guarding route elements based on route metadata and auth state.
 */
export function RouteGuard({
    meta,
    auth,
    options,
    children,
    fallback
}: RouteGuardProps): ReactNode {
    const result = evaluateGuard(meta, auth, options);

    if (!result.allowed) {
        if (typeof fallback === "function") {
            return fallback(result.redirect);
        }
        return fallback ?? null;
    }

    return children;
}
