import { RouteMeta, AuthState, GuardOptions, GuardEvaluation } from "./types";

/**
 * Checks if the current user possesses one of the required roles.
 */
export function hasRole(auth?: AuthState | null, role?: string | string[]): boolean {
    if (!role) return true;
    if (!auth || !auth.roles || auth.roles.length === 0) return false;
    const required = Array.isArray(role) ? role : [role];
    if (required.length === 0) return true;
    return required.some(r => auth.roles!.includes(r));
}

/**
 * Checks if the current user possesses all of the required permissions.
 */
export function hasPermission(auth?: AuthState | null, permission?: string | string[]): boolean {
    if (!permission) return true;
    if (!auth || !auth.permissions || auth.permissions.length === 0) return false;
    const required = Array.isArray(permission) ? permission : [permission];
    if (required.length === 0) return true;
    return required.every(p => auth.permissions!.includes(p));
}

/**
 * Evaluates route metadata against current user authentication state.
 * Returns an evaluation object with permission status, redirect target, and reason.
 */
export function evaluateGuard(
    meta?: RouteMeta,
    auth?: AuthState | null,
    options: GuardOptions = {}
): GuardEvaluation {
    if (!meta) {
        return { allowed: true, reason: "ok" };
    }

    const {
        fallbackRedirect = "/login",
        forbiddenRedirect = "/403",
        guestRedirect = "/"
    } = options;

    const isLogin = Boolean(auth?.isLogin);

    // 1. Guest-only check (e.g. login, register pages shouldn't be accessed by authenticated users)
    if (meta.guestOnly && isLogin) {
        return {
            allowed: false,
            redirect: meta.redirect || guestRedirect,
            reason: "guest_only"
        };
    }

    // 2. Protected route check (explicitly protected or has required roles/permissions)
    const requiresAuth = Boolean(
        meta.protected ||
        (meta.roles && meta.roles.length > 0) ||
        (meta.permissions && meta.permissions.length > 0)
    );

    if (requiresAuth && !isLogin) {
        return {
            allowed: false,
            redirect: meta.redirect || fallbackRedirect,
            reason: "unauthenticated"
        };
    }

    // 3. Role check
    if (meta.roles && meta.roles.length > 0) {
        if (!hasRole(auth, meta.roles)) {
            return {
                allowed: false,
                redirect: meta.redirect || forbiddenRedirect,
                reason: "forbidden"
            };
        }
    }

    // 4. Permission check
    if (meta.permissions && meta.permissions.length > 0) {
        if (!hasPermission(auth, meta.permissions)) {
            return {
                allowed: false,
                redirect: meta.redirect || forbiddenRedirect,
                reason: "forbidden"
            };
        }
    }

    return { allowed: true, reason: "ok" };
}

/**
 * Quick boolean check if a user is allowed to access a route.
 */
export function canAccess(
    auth?: AuthState | null,
    meta?: RouteMeta,
    options?: GuardOptions
): boolean {
    return evaluateGuard(meta, auth, options).allowed;
}
